import{_ as t,o,c as r,a3 as e}from"./chunks/framework.6_aCw6yF.js";const g=JSON.parse('{"title":"关于","description":"关于半亩方塘，以及这一方纸上的留白。","frontmatter":{"title":"关于","description":"关于半亩方塘，以及这一方纸上的留白。","article":false},"headers":[],"relativePath":"about.md","filePath":"about.md"}'),s={name:"about.md"};function i(l,a,n,p,h,d){return o(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="关于" tabindex="-1">关于 <a class="header-anchor" href="#关于" aria-label="Permalink to &quot;关于&quot;">​</a></h1><blockquote><p>半亩方塘一鉴开，天光云影共徘徊。</p><p>问渠那得清如许？为有源头活水来。</p><p>—— 朱熹《观书有感》</p></blockquote><p>这里是「半亩方塘」，一个以码为墨、以字为舟的技术博客。</p><h2 id="一、为什么叫半亩方塘" tabindex="-1">一、为什么叫半亩方塘 <a class="header-anchor" href="#一、为什么叫半亩方塘" aria-label="Permalink to &quot;一、为什么叫半亩方塘&quot;">​</a></h2><p>朱熹写的是读书，也是一个人如何与更大的世界相处。半亩不大，方塘不深，却因为源头活水不断，天光云影都能在其中停留。对写代码的人来说，源头活水也正是开源、源码与不断更新的新知。</p><p>这个博客也是如此。它不追求把每一寸纸都写满，只想在忙碌之外留出一小块安静的地方，放一些关于代码、工具、雨、茶与日常的念头。</p><h2 id="二、这里会写什么" tabindex="-1">二、这里会写什么 <a class="header-anchor" href="#二、这里会写什么" aria-label="Permalink to &quot;二、这里会写什么&quot;">​</a></h2><ul><li><strong>浮生清欢</strong>：听雨、煮茶、旧物、四季，一些慢下来的瞬间。</li><li><strong>工善利器</strong>：从一管羊毫到屏幕上的字距，聊聊工具、分寸与设计。</li><li><strong>匠心造物</strong>、<strong>灵犀智算</strong>：正在落墨，先留一片空白。</li></ul><p>文章不会很频繁，但会尽量写得完整。若某一段恰好与你的此刻相逢，便是这一页最好的去处。</p><h2 id="三、关于作者" tabindex="-1">三、关于作者 <a class="header-anchor" href="#三、关于作者" aria-label="Permalink to &quot;三、关于作者&quot;">​</a></h2><p>闲生，网名 <strong>jokerxian</strong>，中原人，写代码为业，闲时也写字。</p><p>喜欢在雨天磨墨，在晴天晒书；也喜欢在深夜读源码，看逻辑如何一层层长成。相信好的文字不必大声，也能抵达很远的地方。</p><h2 id="四、自己做的小程序" tabindex="-1">四、自己做的小程序 <a class="header-anchor" href="#四、自己做的小程序" aria-label="Permalink to &quot;四、自己做的小程序&quot;">​</a></h2><p>写代码之余，也把日常里那些零散的念头收拢起来，做成了一个小程序——<strong>点滴笔记</strong>，一个基于微信云开发的记录工具。</p><p>它从记账开始，却不止于记账：</p><ul><li><strong>十套主题，随手换</strong>：纸短情长、电影票根、治愈黏土、双人联机、黑胶随身听、双星轨道、植物温室、潮玩积木、水墨雅韵、赛博终端，在「我的 - 主题画廊」里随时切换。</li><li><strong>记账，秒一笔</strong>：分类自定义，旧账不必一笔笔补，微信、支付宝、小米、vivo、随手记、钱迹的账单都能导入 Excel / CSV，可预览，也可整批撤回。</li><li><strong>预算不是摆设</strong>：年、月、分类与个人预算都能设，80% 转黄、95% 转橙、100% 转红，提醒总在超支之前。</li><li><strong>人情往来，有账可查</strong>：礼簿与待还提醒记清人情，支持批量粘贴，一次录一堆。</li><li><strong>还有纪念日、备忘、课表、打卡、找东西</strong>：该有的都有，随手记，随时找。</li></ul><p>说到底，它只是替人记住那些容易散落的小事。若你也有记不完的琐碎，扫码即可一试。</p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/20261124-145038.jpg" alt="点滴笔记小程序码" width="240"><h2 id="五、一点留白" tabindex="-1">五、一点留白 <a class="header-anchor" href="#五、一点留白" aria-label="Permalink to &quot;五、一点留白&quot;">​</a></h2><p>你可以从<a href="/blog-dist/">首页</a>、<a href="/blog-dist/posts/essays/听雨">听雨</a>或<a href="/blog-dist/posts/notes/一管羊毫">一管羊毫</a>开始。</p><p>愿你在这里，读到一点安静。</p>',21)])])}const u=t(s,[["render",i]]);export{g as __pageData,u as default};
